package com.selma.universal;
import android.app.*; import android.content.*; import android.graphics.PixelFormat; import android.opengl.GLSurfaceView; import android.os.*; import android.view.*; import android.widget.*;
public class SelmaOverlayService extends Service {
 WindowManager wm; FrameLayout box; WindowManager.LayoutParams lp; UniversalRenderer renderer;
 public void onCreate(){super.onCreate();channel();startForeground(700,note());DeviceProfile p=DeviceProfile.detect(this);wm=(WindowManager)getSystemService(WINDOW_SERVICE);show(p);}
 void show(DeviceProfile p){box=new FrameLayout(this);box.setBackgroundResource(R.drawable.panel);View visual;if(p.hasGles2){GLSurfaceView gl=new GLSurfaceView(this);gl.setEGLContextClientVersion(2);gl.setZOrderOnTop(true);gl.getHolder().setFormat(PixelFormat.TRANSLUCENT);renderer=new UniversalRenderer(p.quality);gl.setRenderer(renderer);gl.setRenderMode(p.lowRam?GLSurfaceView.RENDERMODE_WHEN_DIRTY:GLSurfaceView.RENDERMODE_CONTINUOUSLY);visual=gl;}else{TextView f=new TextView(this);f.setText("Selma\n2D compatibility mode");f.setGravity(Gravity.CENTER);f.setTextColor(0xFFD9F8FF);visual=f;}TextView c=new TextView(this);c.setText("Selma");c.setTextColor(0xFFD9F8FF);c.setGravity(Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL);c.setPadding(0,0,0,10);box.addView(visual,new FrameLayout.LayoutParams(-1,-1));box.addView(c,new FrameLayout.LayoutParams(-1,-1));int type=Build.VERSION.SDK_INT>=26?WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY:WindowManager.LayoutParams.TYPE_PHONE;lp=new WindowManager.LayoutParams(p.lowRam?300:390,p.lowRam?430:560,type,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCH_MODAL|WindowManager.LayoutParams.FLAG_LAYOUT_NO_LIMITS,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.END;lp.x=20;lp.y=130;box.setOnTouchListener(new Drag());wm.addView(box,lp);}
 Notification note(){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"selma_universal"):new Notification.Builder(this);return b.setContentTitle("Selma Universal").setContentText("Native overlay active").setSmallIcon(android.R.drawable.ic_dialog_info).setOngoing(true).build();}
 void channel(){if(Build.VERSION.SDK_INT>=26)getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("selma_universal","Selma Universal",NotificationManager.IMPORTANCE_LOW));}
 public void onDestroy(){if(box!=null)wm.removeView(box);super.onDestroy();} public IBinder onBind(Intent i){return null;}
 class Drag implements View.OnTouchListener{int sx,sy;float tx,ty;public boolean onTouch(View v,MotionEvent e){if(e.getAction()==0){sx=lp.x;sy=lp.y;tx=e.getRawX();ty=e.getRawY();if(renderer!=null)renderer.setMood(1);return true;}if(e.getAction()==2){lp.x=sx-(int)(e.getRawX()-tx);lp.y=sy+(int)(e.getRawY()-ty);wm.updateViewLayout(box,lp);return true;}if(e.getAction()==1){if(renderer!=null)renderer.setMood(0);return true;}return false;}}
}
